<template><div class="personal-dashboard"><header class="dashboard-head"><div><p class="qs-eyebrow">PERSONAL OVERVIEW</p><h1>{{summary?'欢迎回来，'+summary.user.username:'个人工作台'}}</h1><p>查看设备、任务和收益，让每一步工作都有记录。</p></div><button class="qs-button small" :disabled="loading" @click="load">{{loading?'更新中…':'刷新数据'}} ↻</button></header><div v-if="error" class="qs-error" role="alert">{{error}}</div><section class="dashboard-kpis" aria-label="个人账户统计"><article v-for="item in kpis" :key="item.label" class="qs-panel"><span>{{item.label}}</span><strong>{{item.value}}<small>{{item.unit}}</small></strong><router-link :to="item.path">{{item.action}} ↗</router-link></article></section><div class="dashboard-middle"><section class="qs-panel earnings-panel"><div class="panel-heading"><h2>近 7 日收益</h2><span>{{summary?number(totalEarnings)+' EDG':'—'}}</span></div><div v-if="summary?.earnings_trend.length" class="earning-bars" role="img" :aria-label="'每日收益：'+summary.earnings_trend.map(x=>x.date+' '+x.amount+' EDG').join('，')"><div v-for="point in summary.earnings_trend" :key="point.date"><span>{{number(point.amount)}}</span><i :style="{height:Math.max(3,Math.max(0,point.amount)/maxEarnings*100)+'%'}"></i><small>{{point.date.slice(5)}}</small></div></div><div v-else class="dashboard-empty">{{loading?'正在读取收益记录…':error?'收益记录读取失败':'暂无收益记录'}}<small>设备完成任务后，在这里查看结算记录。</small></div></section><section class="qs-panel quick-panel"><h2>开始下一步工作</h2><router-link v-for="link in quickLinks" :key="link.path" :to="link.path"><span><strong>{{link.title}}</strong><small>{{link.description}}</small></span><b aria-hidden="true">↗</b></router-link></section></div><section class="qs-panel node-panel"><div class="panel-heading"><h2>我的节点</h2><router-link to="/my-nodes">全部节点 ↗</router-link></div><div v-if="summary?.nodes_summary.length" class="node-table-wrap"><table><thead><tr><th>节点名称</th><th>状态</th><th>负载</th><th>已装能力</th></tr></thead><tbody><tr v-for="node in summary.nodes_summary" :key="node.id"><td>{{node.name||node.id}}</td><td><span class="node-status" :class="node.status.toLowerCase()">{{nodeLabel(node.status)}}</span></td><td>{{node.load_pct==null?'—':number(node.load_pct)+'%'}}</td><td>{{number(node.equipped_count)}}</td></tr></tbody></table></div><div v-else class="dashboard-empty">{{loading?'正在读取设备状态…':error?'设备状态读取失败':'尚无节点记录'}}<small>在千手 PC 主动开启共享后，设备信息会显示在这里。</small><router-link class="qs-link" to="/downloads">查看千手 PC 下载 ↗</router-link></div></section><p class="dashboard-timestamp">{{summary?'数据更新于 '+new Date(summary.generated_at).toLocaleString('zh-CN'):'数据以当前账号的服务器记录为准。'}}</p></div></template>
<script setup lang="ts">
import{ref,computed,onMounted,onUnmounted}from'vue';import{myApi,type DashboardSummary}from'../services/api';import{errorMessage}from'../services/identityContract';const summary=ref<DashboardSummary|null>(null),loading=ref(false),error=ref('');let disposed=false,timer:ReturnType<typeof setInterval>|undefined;function number(n:number){return Number.isFinite(Number(n))?Number(n).toLocaleString('zh-CN',{maximumFractionDigits:4}):'—'}const kpis=computed(()=>[{label:'在线节点',value:summary.value?String(summary.value.kpi.nodes_online):'—',unit:summary.value?'/ '+summary.value.kpi.nodes_total:'',path:'/my-nodes',action:'管理设备'},{label:'今日完成分片',value:summary.value?number(summary.value.kpi.tasks_today):'—',unit:'',path:'/tasks',action:'查看任务'},{label:'今日收益',value:summary.value?number(summary.value.kpi.earnings_today):'—',unit:'EDG',path:'/wallet',action:'查看流水'},{label:'累计收益',value:summary.value?number(summary.value.kpi.earnings_total):'—',unit:'EDG',path:'/wallet',action:'收益与账单'}]);const totalEarnings=computed(()=>summary.value?.earnings_trend.reduce((sum,p)=>sum+p.amount,0)||0),maxEarnings=computed(()=>Math.max(1,...(summary.value?.earnings_trend.map(x=>x.amount)||[])));const quickLinks=[{path:'/downloads',title:'使用千手 PC',description:'在桌面上运行智能体与插件'},{path:'/equipment',title:'查看已装能力',description:'了解设备已有的应用和运行能力'},{path:'/account/security',title:'管理账户安全',description:'二次验证、登录设备与会话'}];function nodeLabel(status:string){return({ONLINE:'在线',OFFLINE:'离线',BUSY:'忙碌',online:'在线',offline:'离线',busy:'忙碌'}as Record<string,string>)[status]||status}async function load(){if(loading.value||disposed)return;loading.value=true;try{const result=await myApi.getDashboardSummary();if(!result?.ok||!result.kpi||!Array.isArray(result.earnings_trend)||!Array.isArray(result.nodes_summary))throw new Error('服务返回的工作台数据格式不完整。');if(!disposed){summary.value=result;error.value=''}}catch(e){if(!disposed){summary.value=null;error.value=errorMessage(e,'暂时无法读取工作台数据。')}}finally{if(!disposed)loading.value=false}}onMounted(()=>{load();timer=setInterval(()=>{if(!document.hidden)load()},30000)});onUnmounted(()=>{disposed=true;clearInterval(timer)});
</script>
<style scoped>.dashboard-head{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:30px}.dashboard-head h1{margin:13px 0 11px}.dashboard-head p:last-child{font-size:12px;color:var(--qs-muted);line-height:1.8}.dashboard-kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin:25px 0}.dashboard-kpis article{padding:22px;display:flex;flex-direction:column;gap:21px}.dashboard-kpis article>span{font-size:11px;color:var(--qs-muted)}.dashboard-kpis strong{font:29px ui-monospace,monospace;letter-spacing:-1px;white-space:nowrap}.dashboard-kpis strong small{font:10px var(--qs-font);margin-left:7px;color:var(--qs-muted)}.dashboard-kpis a{font-size:10px;color:var(--qs-accent);text-decoration:none}.dashboard-middle{display:grid;grid-template-columns:1.7fr 1fr;gap:22px;margin-bottom:24px}.earnings-panel,.quick-panel,.node-panel{padding:25px}.panel-heading{display:flex;justify-content:space-between;align-items:center;gap:20px}.panel-heading h2,.quick-panel>h2{font-size:15px;font-weight:500}.panel-heading span,.panel-heading a{font-size:11px;color:var(--qs-muted);text-decoration:none}.earning-bars{height:180px;display:flex;align-items:flex-end;justify-content:space-around;gap:10px;margin:35px 0 20px;padding-bottom:20px}.earning-bars>div{width:100%;max-width:50px;height:100%;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;position:relative;gap:8px}.earning-bars i{display:block;width:60%;min-height:3px;flex-shrink:0;border-radius:3px 3px 0 0;background:linear-gradient(#1668dc,#a6c8f5)}.earning-bars span{font:9px monospace;color:var(--qs-muted)}.earning-bars small{position:absolute;bottom:-22px;font:9px monospace;color:var(--qs-muted);white-space:nowrap}.quick-panel>a{display:flex;align-items:center;justify-content:space-between;padding:21px 0;border-bottom:1px solid var(--qs-line);text-decoration:none;gap:12px}.quick-panel>a:last-child{border-bottom:0;padding-bottom:0}.quick-panel>a strong{font-size:12px;font-weight:500;display:block;margin-bottom:8px}.quick-panel>a small{font-size:10px;color:var(--qs-muted)}.quick-panel>a b{font-weight:400;color:var(--qs-accent)}.dashboard-empty{text-align:center;padding:55px 10px;color:var(--qs-muted);font-size:13px;display:grid;gap:14px}.dashboard-empty small{font-size:11px;line-height:1.8}.dashboard-empty a{font-size:11px}.node-table-wrap{overflow:auto;margin-top:22px}table{width:100%;border-collapse:collapse;font-size:12px;text-align:left;white-space:nowrap}th{padding:12px 16px;background:#f3f6fa;font-weight:400;color:var(--qs-muted);font-size:10px}td{padding:18px 16px;border-bottom:1px solid var(--qs-line)}.node-status{font-size:10px;padding:5px 8px;border:1px solid var(--qs-line);border-radius:5px;color:var(--qs-muted)}.node-status.online{color:var(--qs-accent);background:#e8f5ef}.node-status.busy{color:var(--qs-warn);background:#fff4df}.dashboard-timestamp{font-size:10px;color:var(--qs-muted);margin-top:22px}.dashboard-head .qs-button{white-space:nowrap}@media(max-width:1100px){.dashboard-kpis{grid-template-columns:1fr 1fr}.dashboard-middle{grid-template-columns:1fr}.dashboard-kpis strong{font-size:27px}}@media(max-width:540px){.dashboard-head{align-items:flex-start}.dashboard-head .qs-button{font-size:10px;padding:0 10px}.dashboard-kpis{gap:12px}.dashboard-kpis article{padding:17px}.dashboard-kpis strong{font-size:23px}.earnings-panel,.quick-panel,.node-panel{padding:20px}.panel-heading{gap:10px}.panel-heading span{font-size:10px}}
</style>
